/** Named Sale's router: the asset's format, drawn by the chosen board design
 *  (designs.ts, generated by the template lab) -- the asset's own
 *  choice, else the format's first. An email's hero is a design of its own
 *  (its email design's hero section, compiled alone), under the same id. */
import type { SheetAsset } from '../../../sheet/types';
import { DESIGNS } from './designs';
import { COMPONENTS } from './components';

/** Whether the board has a design for this format. */
export const namedSaleHas = (format: string) => DESIGNS.some(d => d.format === format);

export function NamedSale({ asset, design }: { asset: SheetAsset; design?: string }) {
  const list = DESIGNS.filter(d => d.format === asset.format);
  const d = list.find(x => x.id === design) ?? list[0];
  const Design = d && COMPONENTS[d.component];
  return Design ? <Design asset={asset} /> : <div className="gap">no Named Sale design for {asset.format}</div>;
}
